const config = $('Configuration').first().json;
if (!config.paid_enabled) return [];
const rows = $input.all().map(i => i.json);
const today = $now.setZone('Asia/Seoul').toFormat('yyyy-MM-dd');
const month = today.slice(0,7);
const used = rows.filter(r=>r.budget_month===month).reduce((s,r)=>s+Number(r.actual_usd||0)+Number(r.reserved_usd||0),0);
if (used + config.reserve_usd > config.monthly_budget_usd) return [];
if (rows.filter(r=>r.generation_day===today).length >= config.daily_limit) return [];
if(rows.some(r=>['generation_started','image_submitting'].includes(r.status))) return [];
const canCorrect=r=>config.batch_mode&&Number(r.id)>=4&&Number(r.id)<=33&&r.status==='needs_review'&&r.error&&r.openai_response_id&&Number(r.reserved_usd||0)===0&&Number(JSON.parse(r.topic_map_json||'{}').automaticWritingAttempts||0)<2;
for (const row of rows.filter(r=>canCorrect(r)||(r.status==='ready'&&(!config.target_article_id||r.article_id===config.target_article_id))).sort((a,b)=>(canCorrect(a)?0:1)-(canCorrect(b)?0:1)||a.id-b.id)) {
  try {
    if(!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(row.article_id)||row.article_id.length>90||!row.intent_key||!row.keyword||!row.category) continue;
    if(rows.some(r=>r.id!==row.id&&(r.article_id===row.article_id||r.intent_key===row.intent_key)&&r.status!=='candidate'))continue;
    const normalize=v=>String(v||'').toLowerCase().replace(/[^a-z0-9가-힣]/g,'');
    const mapOf=r=>r.topic_map_json?JSON.parse(r.topic_map_json):{};
    const candidateMap=mapOf(row);
    if(Number(candidateMap.automaticWritingAttempts||0)>=2)continue;
    const activeRows=rows.filter(r=>r.id!==row.id&&!r.article_id?.startsWith('test-')&&r.status!=='candidate');
    const aliases=r=>[r.keyword,...(mapOf(r).aliases||[]),mapOf(r).coreQuestion].filter(Boolean).map(normalize);
    if(activeRows.some(r=>r.article_id===row.article_id||r.intent_key===row.intent_key||aliases(r).some(alias=>aliases(row).includes(alias))))continue;
    const sources=JSON.parse(row.sources_json||'[]');
    if(sources.length<2||new Set(sources.map(s=>s.url)).size<2) continue;
    if(!sources.every(s=>s.title&&/^https:\/\//.test(s.url)&&s.reviewed===true&&s.checkedAt&&s.excerpt?.length>=300)) continue;
    // A queued topic is not an existing article. Keep queue collision checks above,
    // but give the writer only completed article scopes for semantic comparison.
    const existingTopics=activeRows.filter(r=>!['ready','candidate','generation_started'].includes(r.status)&&String(r.title||'').trim()&&Number(r.character_count)>=5000).slice(-80).map(r=>({...mapOf(r),articleId:r.article_id,category:r.category,intentKey:r.intent_key,title:r.title,keyword:r.keyword,status:r.status}));
    const correction=row.body_markdown?{previousMarkdown:String(row.body_markdown).slice(0,20000),visibleCharacters:Number(row.character_count||0),requiredAdditionalCharacters:Math.max(1800,6800-Number(row.character_count||0)),feedback:candidateMap.repairFeedback||row.error||'Complete and check the full article'}:candidateMap.repairFeedback;
    const brief=JSON.stringify({keyword:row.keyword,category:row.category,sources,candidateTopic:candidateMap,existingTopics,existingTitles:existingTopics.map(r=>r.title).filter(Boolean),correction});
    if(brief.length>50000||sources.reduce((n,s)=>n+s.excerpt.length,0)<2000) continue;
    const topic_map_json=JSON.stringify({...candidateMap,automaticWritingAttempts:Number(candidateMap.automaticWritingAttempts||0)+1});
    return [{json:{...row,previous_status:row.status,topic_map_json,brief,revision:Number(row.revision||0)+1,reserved_usd:config.reserve_usd,actual_usd:Number(row.actual_usd||0),budget_month:month,generation_day:today,claim_id:String($execution.id)}}];
  } catch { continue; }
}
return [];

const row=$('Select Draft').first().json;
const response=$input.first().json;
const result={...row,status:'needs_review',title:'',description:'',body_markdown:'',image_prompt:'',character_count:0,error:'',openai_response_id:response.id||''};
const input=Number(response.usage?.input_tokens),output=Number(response.usage?.output_tokens);
if(Number.isFinite(input)&&Number.isFinite(output)){
  const c=$('Configuration').first().json;
  const cached=Math.min(input,Math.max(0,Number(response.usage?.input_tokens_details?.cached_tokens||0)));
  const knownModel=String(response.model||'').startsWith('gpt-5.4-mini');
  if(!knownModel)throw new Error('Unexpected model pricing; preserve reservation and inspect usage');
  result.actual_usd=Number(row.actual_usd||0)+((input-cached)*c.input_usd_per_million+cached*c.cached_input_usd_per_million+output*c.output_usd_per_million)/1000000;
  result.reserved_usd=0;
}
try {
  if(response.error||response.status!=='completed') throw new Error('OpenAI result incomplete; inspect execution before retry');
  const chunks=response.output.flatMap(o=>o.content||[]).filter(c=>c.type==='output_text').map(c=>c.text);
  // n8n may parse JSON-format output_text into an object; the raw API uses strings.
  const draft=chunks.length===1&&chunks[0]!==null&&typeof chunks[0]==='object'&&!Array.isArray(chunks[0])
    ? chunks[0]
    : JSON.parse(chunks.map(text=>typeof text==='string'?text:JSON.stringify(text)).join('').replace(/^```(?:json)?\s*|\s*```$/g,''));
  if(draft.canWrite!==true) throw new Error(draft.holdReason||'Insufficient source evidence');
  result.title=String(draft.title||'');result.description=String(draft.description||'');result.body_markdown=String(draft.markdown||'');result.image_prompt=Array.isArray(draft.imagePrompts)?JSON.stringify(draft.imagePrompts):String(draft.imagePrompt||'');
  const md=result.body_markdown;
  result.character_count=[...md.replace(/!?\[([^\]]*)\]\([^)]*\)/g,'$1').replace(/https?:\/\/\S+/g,'').replace(/[#*`_|>~-]/g,'').replace(/\s+/g,' ').trim()].length;
  if(result.character_count<5000||md.length>60000) throw new Error('Body length check failed');
  if(result.title.length<8||result.title.length>120||result.description.length<20||result.description.length>300) throw new Error('Title or description length check failed');
  if(/<\/?[a-z!][^>]*>/i.test(md)||/!\[[^\]]*\]\(/.test(md)) throw new Error('Unreviewed HTML or images');
  if((md.match(/^## /gm)||[]).length<3) throw new Error('At least three useful sections required');
  const sourceUrls=new Set(JSON.parse(row.sources_json).map(s=>s.url));
  const links=[...md.matchAll(/\]\((https?:\/\/[^\s)]+)\)/g)].map(m=>m[1]);
  if(new Set(links).size<2||links.some(u=>!sourceUrls.has(u))) throw new Error('Sources missing or unexpected links');
  const paragraphs=md.split(/\n\s*\n/).map(p=>p.trim()).filter(p=>p.length>100);
  if(new Set(paragraphs).size!==paragraphs.length) throw new Error('Repeated paragraphs');
  const plans=JSON.parse(result.image_prompt);
  if(plans.length!==5||!plans.every(p=>typeof p==='string'&&p.length>=20&&p.length<=1500))throw new Error('Five distinct image briefs required');
  result.images_json='[]';
  if(!Number.isFinite(input)||!Number.isFinite(output)) throw new Error('Usage could not be reconciled');
  result.status='text_ready';result.reserved_usd=0.015;
} catch(e) {result.error=String(e.message).slice(0,1000);}
return [{json:result}];

const row=$('Check Draft').first().json;
const response=$input.first().json;
const base='https://queue.fal.run/fal-ai/flux/requests/'+response.request_id;
const ok=typeof response.request_id==='string'&&/^[a-zA-Z0-9-]+$/.test(response.request_id)&&response.status_url===base+'/status'&&response.response_url===base;
return [{json:{...row,status:ok?'image_pending':'image_uncertain',fal_request_id:ok?response.request_id:'',fal_status_url:ok?response.status_url:'',fal_response_url:ok?response.response_url:'',error:ok?'':'fal request outcome uncertain; inspect execution, do not resubmit automatically'}}];

for(const item of $input.all()){
  const r=item.json;if(r.status!=='image_pending'||!r.fal_request_id)continue;
  const base='https://queue.fal.run/fal-ai/flux/requests/'+r.fal_request_id;
  if(/^[a-zA-Z0-9-]+$/.test(r.fal_request_id)&&r.fal_status_url===base+'/status'&&r.fal_response_url===base)return [{json:r}];
}
return [];

const row=$('Select Image Request').first().json;const response=$input.first().json;
const images=response.images;
const existing=JSON.parse(row.images_json||'[]');
if(!Array.isArray(existing)||existing.length>=5||!Array.isArray(images)||images.length!==1)throw new Error('Expected one remaining illustration; inspect fal result');
if(response.has_nsfw_concepts?.some(Boolean))throw new Error('Image safety review required');
for(const i of images){if(typeof i.url!=='string'||!/^https:\/\/(?:[a-z0-9-]+\.)*fal\.media\/[^\s\\]+$/i.test(i.url))throw new Error('Unexpected image host');}
if(existing.some(old=>old.url===images[0].url))throw new Error('Image receipt already recorded; do not double count');
const combined=[...existing,...images.map((i,n)=>({url:i.url,alt:row.title+' — AI 생성 설명 이미지 '+(existing.length+n+1),generated:true}))];
return [{json:{...row,status:combined.length===5?'needs_review':'image_more_needed',images_json:JSON.stringify(combined),actual_usd:Number(row.actual_usd||0)+0.003,reserved_usd:(5-combined.length)*0.003,error:''}}];

const row=$('Validate Images').first().json;
const response=$input.first().json;
const base='https://queue.fal.run/fal-ai/flux/requests/'+response.request_id;
const ok=typeof response.request_id==='string'&&/^[a-zA-Z0-9-]+$/.test(response.request_id)&&response.status_url===base+'/status'&&response.response_url===base;
return [{json:{...row,status:ok?'image_pending':'image_uncertain',fal_request_id:ok?response.request_id:'',fal_status_url:ok?response.status_url:'',fal_response_url:ok?response.response_url:'',error:ok?'':'fal request outcome uncertain; inspect execution, do not resubmit automatically'}}];

const c=$('Configuration').first().json;
if(!c.article_id||!c.approved_by||!c.revision)return [];
const row=$input.all().map(i=>i.json).find(r=>r.article_id===c.article_id);
if(!row||row.status!=='needs_review'||Number(row.revision)!==Number(c.revision))throw new Error('Select an existing reviewed article and its current revision');
if(row.article_id.startsWith('test-'))throw new Error('Test articles cannot be approved for publication');
if(row.error||Number(row.character_count)<5000)throw new Error('Resolve editorial errors before approval');
const images=JSON.parse(row.images_json||'[]'),sources=JSON.parse(row.sources_json||'[]'),affiliates=JSON.parse(row.affiliate_json||'[]');
if(images.length<5||images.length>8||sources.length<2||!sources.every(s=>s.reviewed===true))throw new Error('Review at least five images and sources first');
const date=c.scheduled_at?new Date(c.scheduled_at):new Date();if(!Number.isFinite(date.getTime()))throw new Error('Invalid scheduled date');
const at=new Date().toISOString();
const payload={articleId:row.article_id,intentKey:row.intent_key,title:row.title,description:row.description,category:row.category,markdown:row.body_markdown,revision:Number(row.revision),approvedRevision:Number(row.revision),approvedBy:c.approved_by,approvedAt:at,publishedAt:date.toISOString(),sources:sources.map(({title,url,checkedAt})=>({title,url,checkedAt})),images,affiliates,demo:false};
return [{json:{...row,status:'approved',approved_revision:Number(row.revision),approved_by:c.approved_by,approved_at:at,scheduled_at:date.toISOString(),publish_payload:JSON.stringify(payload,null,2)}}];

const c=$('Configuration').first().json;
if(!c.article_id||!c.revision||!c.approved_by)return [];
const rows=$input.all().map(i=>i.json),row=rows.find(r=>r.article_id===c.article_id);
if(!row||row.article_id.startsWith('test-')||row.status!=='needs_review'||Number(row.revision)!==Number(c.revision)||row.error||Number(row.character_count)<5000)return [];
const images=JSON.parse(row.images_json||'[]'),sources=JSON.parse(row.sources_json||'[]');
if(images.length!==5||sources.length<2||!sources.every(s=>s.reviewed))return [];
const month=$now.setZone('Asia/Seoul').toFormat('yyyy-MM');
const used=rows.filter(r=>r.budget_month===month).reduce((s,r)=>s+Number(r.actual_usd||0)+Number(r.reserved_usd||0),0);
if(used+.03>7)return [];
const topics=rows.filter(r=>r.id!==row.id&&Number(r.character_count)>=5000&&r.title&&!r.article_id.startsWith('test-')).map(r=>({articleId:r.article_id,title:r.title,...JSON.parse(r.topic_map_json||'{}')}));
return [{json:{...row,reviewBrief:JSON.stringify({title:row.title,description:row.description,markdown:row.body_markdown,sources,topic:JSON.parse(row.topic_map_json||'{}'),existingTopics:topics}),reserved_usd:.03}}];

const row=$('Select Review').first().json,response=$input.first().json;
const result={...row,status:'needs_review',error:'',reserved_usd:.03};
const input=Number(response.usage?.input_tokens),output=Number(response.usage?.output_tokens);
if(Number.isFinite(input)&&Number.isFinite(output)&&String(response.model||'').startsWith('gpt-5.4-mini')){
 const cached=Math.min(input,Number(response.usage?.input_tokens_details?.cached_tokens||0));
 result.actual_usd=Number(row.actual_usd||0)+((input-cached)*.75+cached*.075+output*4.5)/1e6;result.reserved_usd=0;
}
try{
 if(response.error||response.status!=='completed'||result.reserved_usd)throw new Error('Review outcome uncertain; do not retry automatically');
 const chunks=response.output.flatMap(o=>o.content||[]).filter(c=>c.type==='output_text').map(c=>c.text);
 const review=chunks.length===1&&typeof chunks[0]==='object'?chunks[0]:JSON.parse(chunks.join(''));
 if(review.approved!==true)throw new Error('Editorial review: '+JSON.stringify(review.issues||[]));
 if(!Array.isArray(review.imageAlts)||review.imageAlts.length!==5||review.imageAlts.some(a=>typeof a!=='string'||a.length<4||a.length>250))throw new Error('Review image descriptions missing');
 result.images_json=JSON.stringify(JSON.parse(row.images_json).map((image,index)=>({...image,alt:review.imageAlts[index],generated:true})));
 result.reviewPassed=true;
}catch(e){result.error=String(e.message).slice(0,1000);result.reviewPassed=false;}
return [{json:result}];

const c=$('Configuration').first().json;if(!c.enabled)return [];
if(!/^[\w.-]+$/.test(c.repo_owner)||!/^[\w.-]+$/.test(c.repo_name))throw new Error('Configure GitHub repository');
if(!/^https:\/\/[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?\.[a-z]{2,}\/?$/i.test(c.site_url))throw new Error('Configure HTTPS site origin');
const origin=c.site_url.replace(/\/$/,'');
const rows=$input.all().map(i=>i.json).filter(row=>!row.article_id?.startsWith('test-'));
const row=rows.find(r=>r.status==='publishing')||rows.find(r=>r.status==='approved'&&Date.parse(r.scheduled_at)<=Date.now());
if(!row)return [];
const p=JSON.parse(row.publish_payload);const sources=JSON.parse(row.sources_json).map(({title,url,checkedAt})=>({title,url,checkedAt}));
if(p.articleId!==row.article_id||p.intentKey!==row.intent_key||p.category!==row.category||p.title!==row.title||p.description!==row.description||p.markdown!==row.body_markdown||p.revision!==Number(row.revision)||p.approvedRevision!==Number(row.approved_revision)||p.approvedAt!==row.approved_at||p.approvedBy!==row.approved_by||p.publishedAt!==row.scheduled_at||JSON.stringify(p.sources)!==JSON.stringify(sources)||JSON.stringify(p.images)!==JSON.stringify(JSON.parse(row.images_json))||JSON.stringify(p.affiliates)!==JSON.stringify(JSON.parse(row.affiliate_json||'[]')))throw new Error('Content changed since approval; review the new revision');
if(!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(p.articleId))throw new Error('Invalid article ID');
return [{json:{...row,repo_owner:c.repo_owner,repo_name:c.repo_name,site_url:origin,path:`content/inbox/${p.articleId}-r${p.revision}.json`,public_url:origin+'/notes/'+p.articleId+'/'}}];

const rows=$input.all().map(i=>i.json);
const targets=rows.filter(r=>Number(r.id)>=4&&Number(r.id)<=33&&!r.article_id?.startsWith('test-'));
const completed=targets.filter(r=>r.status==='published').length;
const base={batch:'additional-30-20261015',completed,target:30};
if($runIndex>2400)throw new Error('Batch polling limit reached; inspect state before continuing');
const publishing=targets.find(r=>['approved','publishing'].includes(r.status));
if(publishing)return [{json:{...base,...publishing,action:'publish',workflowId:'yihoqk3fpBOC8P04'}}];
const image=targets.find(r=>r.status==='image_pending');
if(image)return [{json:{...base,...image,action:'images',workflowId:'FeZGGPZKq5IFwDJ9'}}];
if(targets.some(r=>['generation_started','image_submitting','review_started'].includes(r.status)))return [{json:{...base,action:'wait'}}];
const review=targets.find(r=>r.status==='needs_review'&&!r.error&&Number(r.character_count)>=5000&&JSON.parse(r.images_json||'[]').length>=5);
if(review)return [{json:{...base,...review,action:'review',workflowId:'FQg1yF0O4shWkDbQ',approved_by:'Automated evidence and image review; user-authorized publication'}}];
const month=$now.setZone('Asia/Seoul').toFormat('yyyy-MM');
const used=rows.filter(r=>r.budget_month===month).reduce((s,r)=>s+Number(r.actual_usd||0)+Number(r.reserved_usd||0),0);
if(used+.12>7)return [{json:{...base,action:'finished',reason:'Monthly budget reached',used}}];
const ready=targets.find(r=>r.status==='ready'&&Number(JSON.parse(r.topic_map_json||'{}').automaticWritingAttempts||0)<2);
if(ready)return [{json:{...base,...ready,action:'generate',workflowId:'HUqCE3BE3JSNPhI3'}}];
const repair=targets.find(r=>r.status==='needs_review'&&r.error&&r.openai_response_id&&Number(r.reserved_usd||0)===0&&Number(JSON.parse(r.topic_map_json||'{}').automaticWritingAttempts||0)<2);
if(repair){const map=JSON.parse(repair.topic_map_json||'{}');return [{json:{...base,...repair,action:'repair',status:'ready',error:'',topic_map_json:JSON.stringify({...map,repairFeedback:repair.error})}}];}
return [{json:{...base,action:'finished',reason:completed===30?'All requested articles published':'No safely executable rows; inspect failed article checks',pending:targets.filter(r=>r.status!=='published').map(r=>({id:r.article_id,status:r.status,error:r.error}))}}];
